static void ui_launcher_deleted(lv_event_t * e)
{
    if (lv_event_get_target(e) != ui_launcher) return;
    ui_launcher = NULL;
}

void ui_event_launcher_Tile1_0(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    if (event_code != LV_EVENT_CLICKED) {
        return;
    }
    embark_ui_open_clock();
}

void ui_event_launcher_Tile2_0(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    if (event_code != LV_EVENT_CLICKED) {
        return;
    }
    embark_ui_open_settings();
}

